import re,datetime
L=[l for l in t.split('\n') if l.startswith('Date:')]
sel=[]
for l in L:
    m=re.match(r'Date: (\w+ \d+, \d+)',l);d=datetime.datetime.strptime(m.group(1),'%b %d, %Y')
    if datetime.datetime(2023,7,28)<=d<=datetime.datetime(2024,8,2):sel.append(l)
print(len(L),len(sel))
for i,l in enumerate(sel):print(i,l[:60],'...',l[-350:],'\n')

